after:
:root {
  color-scheme: dark;

  /* Surfaces */
  --bg: #050607;
  --bg2: #080a0d;
  --panel: rgba(14, 17, 22, 0.72);
  --panel2: rgba(19, 23, 30, 0.78);

  /* Lines */
  --line: rgba(255, 255, 255, 0.095);
  --line2: rgba(255, 255, 255, 0.16);

  /* Text */
  --text: rgba(245, 247, 250, 0.94);
  --muted: rgba(245, 247, 250, 0.55);
  --faint: rgba(245, 247, 250, 0.34);

  /* Accents and tones */
  --accent: #e9ddc4;
  --accent2: #9db8ff;
  --good: #91f2bd;
  --warn: #ffd27e;
  --bad: #ff8f8f;

  /* Effects */
  --shadow: 0 24px 90px rgba(0, 0, 0, 0.55);
  --shadow-soft: 0 16px 60px rgba(0, 0, 0, 0.35);
  --blur: blur(24px) saturate(1.2);

  /* Typography */
  --font-sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;

  /* Radii */
  --radius-1: 6px;
  --radius-2: 10px;
  --radius-3: 14px;
  --radius-4: 18px;
  --radius-5: 22px;
  --radius-6: 28px;
  --radius-round: 999px;

  /* Spacing scale */
  --space-1: 4px;
  --space-2: 6px;
  --space-3: 8px;
  --space-4: 10px;
  --space-5: 12px;
  --space-6: 14px;
  --space-7: 16px;
  --space-8: 20px;
  --space-9: 24px;
  --space-10: 30px;

  /* Animation */
  --ease-1: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ease-2: cubic-bezier(0.16, 1, 0.3, 1);
  --dur-1: 120ms;
  --dur-2: 200ms;
  --dur-3: 340ms;

  /* Z-index scale */
  --z-ambient: 0;
  --z-app: 1;
  --z-dock: 10;
  --z-modal: 20;
  --z-overlay: 30;
}

/* Inherit the app font from tokens */
body { font-family: var(--font-sans); }

